#include <cstddef>
#include <new>
#include <stdexcept>
#include <utility>

template <class T>
class Vec
{
public:
    Vec() = default;
    ~Vec() {}
    Vec(const Vec& other) {}
    Vec(Vec&& other) noexcept {}
    Vec& operator=(const Vec& other) { return *this; }
    Vec& operator=(Vec&& other) noexcept { return *this; }

    void push_back(const T& value) {}
    void pop_back() {}
    void reserve(std::size_t capacity) {}
    void insert(std::size_t index, const T& value) {}
    void erase(std::size_t index) {}

    T& operator[](std::size_t i) { return data_[i]; }
    const T& operator[](std::size_t i) const { return data_[i]; }
    std::size_t size() const { return size_; }
    std::size_t capacity() const { return capacity_; }
    T* begin() { return data_; }
    T* end() { return data_ + size_; }

private:
    T* data_ = nullptr;
    std::size_t size_ = 0;
    std::size_t capacity_ = 0;
};

solution.solution.cpp:
#include <cstddef>
#include <new>
#include <stdexcept>
#include <utility>

template <class T>
class Vec
{
public:
    Vec() = default;
    ~Vec() { release(); }

    Vec(const Vec& other)
    {
        reserve(other.size_);
        for (std::size_t i = 0; i < other.size_; ++i) new (data_ + i) T(other.data_[i]);
        size_ = other.size_;
    }

    Vec(Vec&& other) noexcept
        : data_(std::exchange(other.data_, nullptr)), size_(std::exchange(other.size_, 0)), capacity_(std::exchange(other.capacity_, 0)) {}

    Vec& operator=(const Vec& other)
    {
        if (this != &other)
        {
            Vec copy(other);
            swap(copy);
        }
        return *this;
    }

    Vec& operator=(Vec&& other) noexcept
    {
        if (this != &other)
        {
            release();
            data_ = std::exchange(other.data_, nullptr);
            size_ = std::exchange(other.size_, 0);
            capacity_ = std::exchange(other.capacity_, 0);
        }
        return *this;
    }

    void push_back(const T& value)
    {
        if (size_ == capacity_)
        {
            T copy(value);                 // value might live inside this vector, so copy it before growing
            grow();
            new (data_ + size_) T(std::move(copy));
        }
        else
        {
            new (data_ + size_) T(value);
        }
        ++size_;
    }

    void pop_back()
    {
        if (size_ == 0) throw std::out_of_range("pop_back on an empty Vec");
        data_[--size_].~T();
    }

    void reserve(std::size_t capacity)
    {
        if (capacity <= capacity_) return;
        T* bigger = static_cast<T*>(::operator new(capacity * sizeof(T)));
        for (std::size_t i = 0; i < size_; ++i)
        {
            new (bigger + i) T(std::move(data_[i]));
            data_[i].~T();
        }
        ::operator delete(data_);
        data_ = bigger;
        capacity_ = capacity;
    }

    void insert(std::size_t index, const T& value)
    {
        if (index > size_) throw std::out_of_range("insert position");
        T copy(value);
        if (size_ == capacity_) grow();
        if (index == size_)
        {
            new (data_ + size_) T(std::move(copy));
        }
        else
        {
            new (data_ + size_) T(std::move(data_[size_ - 1]));      // the last element moves into fresh storage
            for (std::size_t i = size_ - 1; i > index; --i) data_[i] = std::move(data_[i - 1]);
            data_[index] = std::move(copy);
        }
        ++size_;
    }

    void erase(std::size_t index)
    {
        if (index >= size_) throw std::out_of_range("erase position");
        for (std::size_t i = index; i + 1 < size_; ++i) data_[i] = std::move(data_[i + 1]);
        data_[--size_].~T();
    }

    T& operator[](std::size_t i) { return data_[i]; }
    const T& operator[](std::size_t i) const { return data_[i]; }
    std::size_t size() const { return size_; }
    std::size_t capacity() const { return capacity_; }
    T* begin() { return data_; }
    T* end() { return data_ + size_; }

    void swap(Vec& other) noexcept
    {
        std::swap(data_, other.data_);
        std::swap(size_, other.size_);
        std::swap(capacity_, other.capacity_);
    }

private:
    void grow() { reserve(capacity_ == 0 ? 1 : capacity_ * 2); }

    void release()
    {
        for (std::size_t i = 0; i < size_; ++i) data_[i].~T();
        ::operator delete(data_);
        data_ = nullptr;
        size_ = capacity_ = 0;
    }

    T* data_ = nullptr;
    std::size_t size_ = 0;
    std::size_t capacity_ = 0;
};

unitTests:
#include <string>

struct Tracked
{
    static inline int alive = 0;
    int id;
    explicit Tracked(int i) : id(i) { ++alive; }       // no default constructor
    Tracked(const Tracked& o) : id(o.id) { ++alive; }
    Tracked(Tracked&& o) noexcept : id(o.id) { ++alive; }
    Tracked& operator=(const Tracked&) = default;
    Tracked& operator=(Tracked&&) noexcept = default;
    ~Tracked() { --alive; }
};

TEST("push and index") {
    Vec<int> v;
    CHECK_EQ(v.size(), std::size_t{ 0 });
    for (int i = 0; i < 10; ++i) v.push_back(i * i);
    CHECK_EQ(v.size(), std::size_t{ 10 });
    CHECK_EQ(v[3], 9);
    CHECK_EQ(v[9], 81);
    int sum = 0;
    for (int x : v) sum += x;
    CHECK_EQ(sum, 285);
}
TEST("capacity doubles from 1") {
    Vec<int> v;
    std::string seen;
    std::size_t last = v.capacity();
    for (int i = 0; i < 20; ++i) { v.push_back(i); if (v.capacity() != last) { last = v.capacity(); seen += std::to_string(last) + " "; } }
    CHECK_EQ(seen, std::string("1 2 4 8 16 32 "));
    v.reserve(100);
    CHECK_EQ(v.capacity(), std::size_t{ 100 });
    v.reserve(10);
    CHECK_EQ(v.capacity(), std::size_t{ 100 });
    CHECK_EQ(v[19], 19);
}
TEST("insert and erase") {
    Vec<std::string> v;
    for (const char* s : { "b", "d" }) v.push_back(s);
    v.insert(0, "a");
    v.insert(2, "c");
    v.insert(4, "e");
    std::string all;
    for (auto& s : v) all += s;
    CHECK_EQ(all, std::string("abcde"));
    v.erase(1);
    v.erase(3);
    all.clear();
    for (auto& s : v) all += s;
    CHECK_EQ(all, std::string("acd"));
    CHECK_THROWS(v.insert(4, "x"));
    CHECK_THROWS(v.erase(3));
    v.pop_back(); v.pop_back(); v.pop_back();
    CHECK_THROWS(v.pop_back());
}
TEST("types without a default constructor, constructed only when needed") {
    {
        Vec<Tracked> v;
        v.reserve(8);
        CHECK_EQ(Tracked::alive, 0);
        for (int i = 0; i < 5; ++i) v.push_back(Tracked(i));
        CHECK_EQ(Tracked::alive, 5);
        v.erase(0);
        CHECK_EQ(Tracked::alive, 4);
        CHECK_EQ(v[0].id, 1);
        for (int i = 0; i < 20; ++i) v.push_back(Tracked(100 + i));
        CHECK_EQ(Tracked::alive, 24);
        v.insert(2, Tracked(-1));
        CHECK_EQ(v[2].id, -1);
        CHECK_EQ(v[3].id, 3);
        CHECK_EQ(Tracked::alive, 25);
    }
    CHECK_EQ(Tracked::alive, 0);
}
TEST("copies are independent, moves steal") {
    Vec<std::string> a;
    a.push_back("one"); a.push_back("two");
    Vec<std::string> b = a;
    b[0] = "changed";
    CHECK_EQ(a[0], std::string("one"));
    Vec<std::string> c = std::move(a);
    CHECK_EQ(a.size(), std::size_t{ 0 });
    CHECK_EQ(c[1], std::string("two"));
    a = c;
    CHECK_EQ(a.size(), std::size_t{ 2 });
    c = std::move(b);
    CHECK_EQ(c[0], std::string("changed"));
    a = a;
    CHECK_EQ(a[1], std::string("two"));
}
TEST("pushing an element of the same vector") {
    Vec<std::string> v;
    v.push_back("first");
    for (int i = 0; i < 6; ++i) v.push_back(v[0]);
    CHECK_EQ(v.size(), std::size_t{ 7 });
    CHECK_EQ(v[6], std::string("first"));
}
TEST("no leaks") {
    CHECK_NO_LEAK({ Vec<std::string> v; for (int i = 0; i < 50; ++i) v.push_back(std::string(40, 'x')); Vec<std::string> w = v; w.erase(3); v = std::move(w); });
}

